import { createV3MacroState, runV3MacroMonth, V3_EXTERNAL_CHANNELS, V3_POLICY_CHANNELS } from '../v3-macro-simulation.js';
import { V3_SPI_COICOP12_WEIGHTS_PER_MILLE } from '../v3-price-index.js';

const phaseNames = { upswing: 'Aufschwung', boom: 'Hochkonjunktur / Boom', downturn: 'Abschwung', trough: 'Tiefstand' };
const externalNames = { fx_imported_inputs: 'Wechselkurs & importierte Vorleistungen', foreign_demand: 'Auslandsnachfrage', international_supply: 'Internationale Lieferfähigkeit' };
const policyNames = { monetary: 'Geldpolitik', fiscal: 'Finanzpolitik', growth: 'Wachstumspolitik', tariff: 'Tarifpolitik', labor_market: 'Arbeitsmarktpolitik', environmental: 'Umweltpolitik', demand_oriented: 'Nachfrageorientierte Politik', supply_oriented: 'Angebotsorientierte Politik' };
const sourceInfo = { observed: ['Beobachteter Quellenwert','observed'], derived: ['Abgeleiteter Wert','derived'], synthetic_fixture: ['Synthetische Regression-Fixture','synthetic'], synthetic_scenario: ['Synthetischer Szenariopfad · unkalibriert','synthetic'], unavailable: ['Nicht verfügbar','unavailable'], synthetic: ['Synthetische Szenarioannahme','synthetic'] };
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const badge = type => { const [label, cls] = sourceInfo[type] ?? ['Modellannahme','synthetic']; return `<span class="source-badge ${cls}">${label}</span>`; };
const fmt = (value, digits=2) => Number.isFinite(value) ? new Intl.NumberFormat('de-DE',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value) : '—';
const monthPeriod = index => new Date(Date.UTC(2027,index,1)).toISOString().slice(0,7);

// Exact fixture values below follow the documented A02 regression cases; this is a demo fixture, not a product default.
export function createDocumentedSyntheticMacroRun(quoteMode='none') {
  if (!['none','indicative','expired'].includes(quoteMode)) throw new TypeError('Unbekannter Angebotsmodus');
  const profile = {
    runId:'run-fixture-1', scenarioId:'scenario-fixture', seed:'seed-17', profileVersion:'fixture-v1', sourceSnapshotId:'fixture-snapshot',
    cycleParameters:{lowGapPct:-2,highGapPct:2,positiveMomentumPct:0.1,negativeMomentumPct:-0.1,persistencePeriods:1,parameterSetId:'cycle-fixture-v1',sourceRef:'synthetic-fixture:cycle'},
    mroFutureRule:{formulaId:'affine_spi_yoy_fixture',referenceMroPctPA:1,coefficient:0.5,referenceInflationPct:2,lagPeriods:1,parameterSetId:'mro-fixture-v1',sourceRef:'synthetic-fixture:mro-rule',uncertaintyBand:{low:-0.5,base:0,high:0.5}},
  };
  const source = label => ({sourceType:'synthetic_fixture',sourceRef:`fixture:${label}`,unit:'index',value:100,effectiveFrom:'2027-01-01',lagPeriods:0,uncertaintyBand:{low:-1,base:0,high:1},firmExposure:`fixture:${label}`,expectedOutcome:'directional_only'});
  let state = createV3MacroState(profile);
  const originalState = structuredClone(state);
  const priorIndexes=[]; const snapshots=[];
  for(let i=0;i<14;i+=1){
    const period=monthPeriod(i), level=100+i, activityIndex=100;
    const monthly={period,parameterSetId:'inputs-fixture-v1',componentIndexes:Object.fromEntries(Object.keys(V3_SPI_COICOP12_WEIGHTS_PER_MILLE).map(id=>[id,level])),priorMonthlySpiIndexes:[...priorIndexes],componentSourceType:'synthetic_fixture',componentSourceRef:`fixture:spi:${period}`,activity:{activityIndex,trendIndex:100,priorActivityIndex:activityIndex/1.002,sourceType:'synthetic_fixture',sourceRef:`fixture:activity:${period}`,observedQuarterly:null},externalChannels:Object.fromEntries(V3_EXTERNAL_CHANNELS.map(name=>[name,source(name)])),policyChannels:Object.fromEntries(V3_POLICY_CHANNELS.map(name=>[name,{...source(name),measure:`fixture ${name} measure`,goal:'synthetic test goal',intermediateIndicator:`fixture indicator ${name}`,firmExposure:`fixture exposure ${name}`,expectedOutcome:'directional test only',counterEffect:'synthetic fixture counter-effect',effectGroupId:`group-${name}`,accountingClass:'information_plan'}]))};
    if(i===13 && quoteMode!=='none') monthly.newCreditRequest={creditRequestId:'credit-request-fixture',indicativeSpreadPp:2,indicativeTermMonths:36,validFrom:'2028-02-01',validUntil:quoteMode==='expired'?'2028-02-15':'2028-02-29',mroBasePctPA:1,sourceRef:'synthetic-fixture:credit-terms',parameterSetId:'quote-fixture-v1'};
    const result=runV3MacroMonth(state,monthly);
    if(!result.ok) throw new Error(result.error?.message ?? 'Makro-Fixture konnte nicht berechnet werden');
    state=result.state; snapshots.push(result.snapshot); priorIndexes.push(result.snapshot.spi.index);
  }
  return {state,originalState,snapshots};
}

export function renderMacroSnapshot(snapshot, previousSnapshot=null) {
  const period=esc(snapshot.period), phase=phaseNames[snapshot.phaseState.phase] ?? 'Nicht klassifiziert', priorPhase=previousSnapshot?(phaseNames[previousSnapshot.phaseState.phase] ?? 'Nicht klassifiziert'):'Start';
  const reasons={initial_or_maintained:'Einstieg oder Phase beibehalten',hysteresis_pending:'Wechselkandidat wartet auf die festgelegte Hysterese',hysteresis_satisfied:'Wechselkandidat erfüllt die Hysterese',explicit_scenario_shock:'Expliziter Szenario-Schock',missing_activity_indicator:'Indikatoren fehlen; vorherige Phase bleibt bestehen',non_adjacent_transition_requires_explicit_shock:'Nicht benachbarter Wechsel ohne Schock nicht zugelassen'};
  const scheduled=new Map(snapshot.scheduledEvents.map(e=>[`${e.channel}:${e.eventKey}`,e]));
  const channelCard=(name,record,type)=>{const event=scheduled.get(`${type}:${name}`), band=record.uncertaintyBand;return `<article class="channel-card"><div class="card-heading"><span class="source-badge ${record.sourceType==='observed'?'observed':'synthetic'}">${esc(sourceInfo[record.sourceType]?.[0]??'Modellannahme')}</span><small>${esc(record.sourceRef)}</small></div><h3>${esc(type==='external'?externalNames[name]:policyNames[name])}</h3><p>${esc(record.measure??'Szenarioindikator')}: <strong>${fmt(record.value,2)} ${esc(record.unit)}</strong></p><p>${esc(record.expectedOutcome??'Wirkungsrichtung offen')} · Exposure: ${esc(record.firmExposure)}</p><div class="channel-meta"><div><strong>Wirksam ab</strong>${esc(record.effectiveFrom)} · ${Number(record.lagPeriods)} Monat(e)</div><div><strong>Geltung laut Runtime</strong>${esc(event?.effectivePeriod??'—')}</div><div><strong>Unsicherheitsband</strong>${band?`${fmt(band.low)} / ${fmt(band.base)} / ${fmt(band.high)} ${esc(record.unit)}`:'nicht angegeben'}</div><div><strong>Gegenwirkung</strong>${esc(record.counterEffect??'separat im Szenario zu prüfen')}</div></div></article>`;};
  const mro=snapshot.mro, quote=snapshot.financingHandoff, spi=snapshot.spi;
  const mroHtml=mro.valuePctPA==null?`<p>Kein MRO-Wert für diese Periode: ${esc(mro.reason??'Quelle/Szenariopfad nicht verfügbar')}.</p>${badge('unavailable')}`:`<div class="metric"><span class="label">MRO-Indikator</span><output>${fmt(mro.valuePctPA)} % p. a.</output>${badge(mro.sourceType)}<small>Quelle: ${esc(mro.sourceRef??'—')} · ${mro.lagPeriods??0} Monat(e) Verzögerung</small></div>${mro.uncertaintyBand?`<p class="hint">Unsicherheitsband low/base/high: ${fmt(mro.uncertaintyBand.low)} / ${fmt(mro.uncertaintyBand.base)} / ${fmt(mro.uncertaintyBand.high)} Prozentpunkte.</p>`:''}${mro.assumptionStatus?`<p class="hint">Status: ${esc(mro.assumptionStatus)}. Keine EZB-Beobachtung und keine kalibrierte Prognose.</p>`:''}<p class="hint">Referenzperiode: ${esc(mro.referencePeriod??mro.observedPeriod??snapshot.period)} · Wirksamkeitsdatum: ${esc(mro.effectiveFrom??'Szenarioperiode')}</p>`;
  const quoteHtml=!quote?'<p>Für diesen Snapshot liegt keine indikative Anfrage vor.</p>':`<p><span class="tag ${quote.status==='expired'?'pending':'good'}">${quote.status==='expired'?'Abgelaufen':'Indikativ'}</span> · ${badge(quote.sourceType)}</p><div class="quote-terms"><div><strong>Nur indikativ</strong>${fmt(quote.indicativeRatePctPA)} % p. a.</div><div><strong>Laufzeitwunsch</strong>${quote.indicativeTermMonths} Monate</div><div><strong>Gültigkeit</strong>${esc(quote.validFrom)} bis ${esc(quote.validUntil)}</div></div><p class="hint">Keine Kreditannahme, kein Vertrag und keine Änderung bestehender Kredite.</p>`;
  return `<section class="panel" data-period="${period}"><div class="snapshot-head"><div><p class="eyebrow">Monatssnapshot · ${period}</p><h2>${phase}</h2><p class="identity">Szenario ${esc(snapshot.scenarioId)} · Lauf ${esc(snapshot.runId)} · Seed ${esc(snapshot.seed)} · Modell ${esc(snapshot.modelVersion)}</p></div><span class="source-badge synthetic">Synthetischer Monatslauf</span></div><div class="transition"><strong>Phasenübergang:</strong> ${priorPhase} → ${phase}. ${esc(reasons[snapshot.phaseState.reason]??snapshot.phaseState.reason)}. Lage/Momentum folgen den Profilparametern; keine amtliche Phasenklassifikation.</div><div class="grid"><article class="metric"><span class="label">Aktivitätslücke zum Modelltrend</span><output>${fmt(snapshot.activity.activityGapPct)} %</output>${badge(snapshot.activity.sourceType)}<small>${esc(snapshot.activity.sourceRef)} · Index ${fmt(snapshot.activity.activityIndex)} / Trend ${fmt(snapshot.activity.trendIndex)}</small></article><article class="metric"><span class="label">Aktivitätsmomentum m/m</span><output>${fmt(snapshot.activity.activityMomentumPct)} %</output>${badge(snapshot.activity.sourceType)}<small>Modellinput, nicht nationale Monatsstatistik</small></article><article class="metric"><span class="label">Profilparameter</span><output>${esc(snapshot.parameterSetId)}</output><small>Zyklusschwellen und Periodenregeln sind im Laufprofil versioniert.</small></article><article class="metric"><span class="label">V3-Spielpreisindex (SPI)</span><output>${fmt(spi.index)}</output>${badge(spi.sourceType)}<small>2020=100 · ${esc(spi.basketVersion)} · ${esc(spi.sourceRef)}</small></article><article class="metric"><span class="label">SPI-Inflation m/m</span><output>${fmt(spi.monthOverMonthInflation)} %</output>${badge('derived')}<small>Runtime-Ausgabe; fehlende Historie bleibt „—“.</small></article><article class="metric"><span class="label">SPI-Inflation y/y</span><output>${fmt(spi.yearOverYearInflation)} %</output>${badge('derived')}<small>Spielindex, kein amtlicher VPI/HVPI und keine Inflationserwartung.</small></article></div><section class="section"><div class="section-heading"><div><h2>EZB-/MRO-Kanal</h2><p>Beobachtete Quelle, Modellpfad oder fehlende Historie sind getrennt ausgewiesen.</p></div></div><article class="detail-card">${mroHtml}</article></section><section class="section"><div class="section-heading"><div><h2>Außenwirtschaft</h2><p>Lag und Unsicherheit bleiben sichtbar; keine direkte Unternehmensbuchung.</p></div></div><div class="channels">${V3_EXTERNAL_CHANNELS.map(name=>channelCard(name,snapshot.externalChannels[name],'external')).join('')}</div></section><section class="section"><div class="section-heading"><div><h2>Wirtschaftspolitik</h2><p>Politikfelder zeigen Szenarioannahmen, Exposition, Verzögerung und Gegenwirkung.</p></div></div><div class="channels">${V3_POLICY_CHANNELS.map(name=>channelCard(name,snapshot.policyChannels[name],'policy')).join('')}</div></section><section class="section"><div class="section-heading"><div><h2>Finanzierungshinweis</h2><p>Nur eine neue Anfrage kann eine zeitgebundene Konditionsanzeige auslösen.</p></div></div><article class="detail-card quote ${quote?.status==='expired'?'expired':''}">${quoteHtml}<div class="guard">Informative Übergabe: keine Ledger-/Cash-/Forderungs-/Verbindlichkeits-/Bestands-/Altvertragswirkung.</div></article></section></section>`;
}

if (typeof document !== 'undefined') {
  const $=id=>document.getElementById(id), runButton=$('run-demo'), select=$('period-select'), output=$('snapshot'), quoteMode=$('quote-mode'); let run=null;
  const show=()=>{if(!run)return;const i=Number(select.value);output.innerHTML=renderMacroSnapshot(run.snapshots[i],run.snapshots[i-1]??null);output.hidden=false;$('empty-state').hidden=true;};
  runButton.addEventListener('click',()=>{try{run=createDocumentedSyntheticMacroRun(quoteMode.value);select.innerHTML=run.snapshots.map((s,i)=>`<option value="${i}">${esc(s.period)}</option>`).join('');select.disabled=false;select.value=String(run.snapshots.length-1);$('run-status').textContent='Demo geladen · synthetisch';$('run-status').className='tag good';show();$('live-status').textContent='14 Monats-Snapshots aus dem dokumentierten synthetischen Fixture geladen.';}catch(error){run=null;output.hidden=true;$('empty-state').hidden=false;$('run-status').textContent='Lauf fehlgeschlagen';$('run-status').className='tag pending';$('live-status').textContent=error.message;}});
  select.addEventListener('change',show);
}

